import type {ReactNode} from 'react'
import {Stack} from '@primer/react'
import {clsx} from 'clsx'
import styles from './SummaryCardTwoSectionBody.module.css'

export interface SummaryCardTwoSectionBodyProps {
  primarySection: ReactNode
  secondarySection: ReactNode
  showDivider?: boolean
  stackGap?: 'condensed' | 'normal' | 'spacious'
  stackPadding?: 'none' | 'condensed' | 'normal' | 'spacious'
  className?: string
  testId?: string
}

export function SummaryCardTwoSectionBody({
  primarySection,
  secondarySection,
  showDivider = true,
  stackGap = 'spacious',
  stackPadding = 'normal',
  className,
  testId = 'two-section-body',
}: SummaryCardTwoSectionBodyProps) {
  return (
    <Stack
      gap={stackGap}
      padding={stackPadding}
      className={clsx(styles.stackResponsive, className)}
      align="stretch"
      data-testid={testId}
    >
      <div className={styles.section}>{primarySection}</div>
      {showDivider && <div className={styles.dividerResponsive} />}
      <div className={styles.section}>{secondarySection}</div>
    </Stack>
  )
}
